import {patterns} from './pattern-data.mjs';
const e=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
import {videos} from './video-catalog.mjs';
export {videos};
export function figure(p){return `<figure class="aq-source-figure"><a class="aq-zoom" href="${p.src}" target="_blank" rel="noopener" aria-label="Open full-size diagram: ${e(p.title)}"><img loading="lazy" decoding="async" src="${p.src}" alt="${e(p.alt)}"><span>Full size ↗</span></a><figcaption><strong>${e(p.title)}</strong><p lang="id">${e(p.cue)}</p><a href="${p.source}" target="_blank" rel="noopener">Source: AWS Samples ↗</a></figcaption></figure>`;}
export function clip(v,related=false){return `<article class="aq-clip"><div><small>${e(v.publisher)} · ${related?'RELATED TOPIC':'SERVICE VIDEO'}</small><h3>${e(v.title)}</h3>${related?'<p class="fine">Video pendukung tentang keluarga layanan; bukan tutorial khusus fitur yang dipilih.</p>':''}<p lang="id">${e(v.cue)}</p></div><div class="aq-player"><button type="button" data-play-clip="${v.id}" class="button" aria-label="Load video: ${e(v.title)}">▷ Load video</button> <a href="${v.url}" target="_blank" rel="noopener">Watch on YouTube ↗</a></div></article>`;}
export function matchVideos(ids){return videos.filter(v=>[...v.services,...v.relatedServices].some(id=>ids.includes(id))).sort((a,b)=>Number(b.services.some(id=>ids.includes(id)))-Number(a.services.some(id=>ids.includes(id))));}
export function initMedia(){document.addEventListener('click',evt=>{const btn=evt.target.closest('button[data-play-clip]');if(!btn)return;const v=videos.find(x=>x.id===btn.dataset.playClip);if(!v)return;const frame=document.createElement('iframe');frame.title=v.title;frame.src='https://www.youtube-nocookie.com/embed/'+v.id;frame.allowFullscreen=true;frame.referrerPolicy='strict-origin-when-cross-origin';btn.replaceWith(frame);});}
export function relatedMedia(ids){const picks=patterns.map(p=>[p,p.services.filter(id=>ids.includes(id)).length]).filter(([,n])=>n).sort((a,b)=>b[1]-a[1]).map(([p])=>p),clips=matchVideos(ids);if(!(picks.length+clips.length))return '';return `<section class="aq-context-media"><a class="fine" href="#videos/${ids[0]}">Browse all videos for this service →</a><h3>Look closer · Lihat contohnya</h3>${picks[0]?figure(picks[0]):''}${clips.slice(0,1).map(v=>clip(v,!v.services.some(id=>ids.includes(id)))).join('')}${picks.length>1||clips.length>1?`<details><summary>More related media</summary>${picks.slice(1).map(figure).join('')}${clips.slice(1).map(v=>clip(v,!v.services.some(id=>ids.includes(id)))).join('')}</details>`:picks.slice(1).map(figure).join('')+clips.slice(1).map(v=>clip(v,!v.services.some(id=>ids.includes(id)))).join('')}</section>`;}
export function mediaLibrary(){return `<p class="section-context">VISUAL LEARNING / ENGLISH × BAHASA</p><h1>Visual library.</h1><p class="lede">Pilih layanan, lihat contohnya, lalu jelaskan kembali dengan kata-katamu sendiri.</p><nav class="aq-media-links" aria-label="Visual learning tools"><a class="button" href="#videos">Watch the mechanism · ${videos.length} videos →</a><a class="button" href="#visuals">176 illustrated service cards →</a><a class="button" href="#architecture">6 interactive walkthroughs →</a></nav><h2>Architecture in practice</h2><div class="aq-source-grid">${patterns.map(figure).join('')}</div><h2>Watch the mechanism</h2><p>${videos.length} selected AWS videos. Browse by service or category, including related explanations for individual features.</p><a class="button primary" href="#videos">Find a video for your service →</a><div class="aq-clip-grid">${videos.slice(0,4).map(v=>clip(v)).join('')}</div>`;}
export function filterVideos(data,{category='all',service='all',query=''}={}){const list=data.categories.filter(c=>category==='all'||c.id===category).flatMap(c=>c.services),ids=list.map(s=>s.id),q=query.trim().toLowerCase(),names=Object.fromEntries(list.map(s=>[s.id,[s.name,s.expansion,s.cue].join(' ')]));return (service==='all'?videos:matchVideos([service])).filter(v=>[...v.services,...v.relatedServices].some(id=>ids.includes(id))&&[v.title,v.cue,...v.services.map(id=>names[id]),...v.relatedServices.map(id=>names[id])].join(' ').toLowerCase().includes(q));}
export function renderVideos(root,data,initial){
 const all=data.categories.flatMap(c=>c.services);let service=all.some(s=>s.id===initial)?initial:'all',category='all',query='',limit=12;
 const direct=all.filter(s=>videos.some(v=>v.services.includes(s.id))).length,covered=all.filter(s=>matchVideos([s.id]).length).length;
 root.innerHTML=`<p class="section-context">VISUAL LIBRARY / WATCH · TRACE · EXPLAIN</p><h1>Watch the mechanism.</h1><p class="lede">Pilih layanan, tonton penjelasannya, lalu jawab pertanyaan panduan.</p><p>${videos.length} curated videos · ${direct} services/features with focused videos · ${covered-direct} with related videos</p><div class="aq-video-filters"><label>Search videos<input type="search" id="video-search" placeholder="Service or video title…"></label><label>Category<select id="video-category"><option value="all">All categories</option>${data.categories.map(c=>`<option value="${c.id}">${e(c.title)}</option>`).join('')}</select></label><label>Service or feature<select id="video-service"></select></label></div><div id="video-context"></div><p id="video-count" role="status"></p><div id="video-results" class="aq-clip-grid"></div><button id="video-more" class="button">Show more videos</button><p class="fine">Selected videos include older introductions and conference sessions. Use current AWS documentation for availability, limits and console steps. If embedding is blocked, use the YouTube link.</p><a href="#media">← Back to diagrams</a>`;
 const by=id=>root.querySelector('#'+id);
 function options(){by('video-service').innerHTML='<option value="all">All services & features</option>'+data.categories.filter(c=>category==='all'||c.id===category).map(c=>`<optgroup label="${e(c.title)}">${c.services.map(s=>`<option value="${s.id}">${e(s.name)}</option>`).join('')}</optgroup>`).join('');by('video-service').value=service;}
 function draw(){const rows=filterVideos(data,{category,service,query}),chosen=all.find(s=>s.id===service);by('video-context').innerHTML=chosen?`<div class="aq-video-selected"><strong>${e(chosen.name)}</strong><p>${e(chosen.cue)}</p><a href="#learn/${chosen.lesson}">Open lesson →</a> · <a href="https://www.youtube.com/results?search_query=${encodeURIComponent('Amazon Web Services '+chosen.name+' AWS official')}" target="_blank" rel="noopener">Find more on YouTube ↗</a></div>`:'';by('video-count').textContent=rows.length+' matching videos · showing '+Math.min(limit,rows.length);by('video-results').innerHTML=rows.length?rows.slice(0,limit).map(v=>clip(v,service!=='all'&&!v.services.includes(service))).join(''):'<div class="empty"><h2>No verified video in this selection yet.</h2><p>Clear the search or select another service. The YouTube search link above can help you explore further; search results have not been reviewed.</p></div>';by('video-more').hidden=rows.length<=limit;}
 by('video-category').onchange=ev=>{category=ev.target.value;service='all';limit=12;options();history.replaceState(null,'','#videos');draw();};by('video-service').onchange=ev=>{service=ev.target.value;limit=12;history.replaceState(null,'',service==='all'?'#videos':'#videos/'+service);draw();};by('video-search').oninput=ev=>{query=ev.target.value;limit=12;draw();};by('video-more').onclick=()=>{limit+=12;draw();};options();draw();
}
